Here's how to save/restore draft text using Window lifecycle events:

**App.xaml.cs** — Override `CreateWindow` and hook `Stopped`/`Resumed`/`Destroying`:

```csharp
public partial class App : Application
{
    protected override Window CreateWindow(IActivationState? activationState)
    {
        var window = base.CreateWindow(activationState);

        window.Stopped += (s, e) =>
            Preferences.Set("draft_text", GetDraftText());

        window.Resumed += (s, e) =>
            RestoreDraftText(Preferences.Get("draft_text", string.Empty));

        // Android back-button can skip Stopped entirely
        window.Destroying += (s, e) =>
            Preferences.Set("draft_text", GetDraftText());

        return window;
    }

    private string GetDraftText()
    {
        if (Windows[0].Page is AppShell shell
            && shell.CurrentPage is NotePage page)
            return page.ViewModel.DraftText;
        return string.Empty;
    }

    private void RestoreDraftText(string text)
    {
        if (Windows[0].Page is AppShell shell
            && shell.CurrentPage is NotePage page)
            page.ViewModel.DraftText = text;
    }
}
```

**Or use a custom Window subclass** (cleaner approach):

```csharp
public class AppWindow : Window
{
    public AppWindow(Page page) : base(page) { }

    protected override void OnStopped()
    {
        base.OnStopped();
        Preferences.Set("draft_text", GetCurrentDraft());
    }

    protected override void OnResumed()
    {
        base.OnResumed();
        SetCurrentDraft(Preferences.Get("draft_text", string.Empty));
    }

    protected override void OnDestroying()
    {
        base.OnDestroying();
        Preferences.Set("draft_text", GetCurrentDraft());
    }
}
```

**Key points:**

| Concern | Guidance |
|---------|----------|
| **Where to save** | `OnStopped` (app backgrounded) + `OnDestroying` (Android back button) |
| **Where to restore** | `OnResumed` — fires when returning from background |
| **Storage** | `Preferences` for small strings; file I/O for larger data |
| **Speed** | Keep handlers under 1–2 seconds to avoid ANR/watchdog kills |
| **First launch** | `Resumed` does NOT fire on initial launch — load saved drafts in your page's `OnAppearing` or `Created` instead |

`Preferences.Set`/`Get` is ideal for a single draft string. If you have multiple fields or large content, serialize to a JSON file in `FileSystem.AppDataDirectory`.
